"""Adapter for independent local niches generated by ``nicheflow_dkd``.

The model writes evaluator-facing ``x`` and ``pos`` arrays only. Biological-group and condition
metadata remain in a sidecar and are handled by the experiment runner before this adapter is
called; they must never be discarded and replaced by cell-pooled evaluation.
"""

from __future__ import annotations

import json
from pathlib import Path

import numpy as np

from paired_slides_eval.contract import GeneratedNiches, TargetSlide
from paired_slides_eval.evaluate import evaluate


def load_dkd_generated(path: str | Path) -> tuple[GeneratedNiches, dict[str, object]]:
    """Load an immutable DKD generated, real-control, or corruption artifact."""
    path = Path(path)
    sidecar = path.with_suffix(".json")
    if not sidecar.exists():
        raise FileNotFoundError(f"Missing DKD generation sidecar: {sidecar}")
    with np.load(path, allow_pickle=False) as arrays:
        if set(arrays.files) != {"x", "pos"}:
            raise ValueError(f"Expected exactly x/pos arrays; found {sorted(arrays.files)}")
        generated = GeneratedNiches(x=arrays["x"], pos=arrays["pos"])
    metadata = json.loads(sidecar.read_text(encoding="utf-8"))
    for required in ("seed", "condition", "held_out_group"):
        if required not in metadata:
            raise ValueError(f"DKD sidecar is missing required field {required!r}.")
    artifact_kind = metadata.get("artifact_kind")
    if artifact_kind is None and "checkpoint" in metadata:
        # Backward compatibility for the first immutable T0 artifact contract.
        artifact_kind = "generated_niches"
        metadata["artifact_kind"] = artifact_kind
    if artifact_kind is None:
        raise ValueError("DKD sidecar is missing required field 'artifact_kind'.")
    if artifact_kind == "generated_niches" and "checkpoint" not in metadata:
        raise ValueError("Generated DKD sidecar is missing required field 'checkpoint'.")
    return generated, metadata


def evaluate_dkd_group(
    target_path: str | Path,
    generated_path: str | Path,
    *,
    seed: int,
) -> tuple[dict[str, float], dict[str, object]]:
    """Evaluate one held-out group in its frozen train-fitted local-niche space."""
    with np.load(target_path, allow_pickle=False) as arrays:
        if set(arrays.files) != {"x", "pos"}:
            raise ValueError("DKD target NPZ must contain exactly x and pos arrays.")
        x = np.asarray(arrays["x"])
        pos = np.asarray(arrays["pos"])
    if x.ndim != 3 or pos.ndim != 3 or x.shape[:2] != pos.shape[:2]:
        raise ValueError("DKD target must use x[B,K,D] and pos[B,K,2].")
    target = TargetSlide(x=x.reshape(-1, x.shape[-1]), pos=pos.reshape(-1, pos.shape[-1]))
    generated, metadata = load_dkd_generated(generated_path)
    metrics = evaluate(
        target,
        generated,
        groups=("distribution", "c2st"),
        seed=seed,
        prefix="",
    )
    expected = {
        "mmd2/x",
        "mmd2/pos",
        "ot_w1/x",
        "ot_w1/pos",
        "ot_w2/x",
        "ot_w2/pos",
        "c2st/acc",
        "c2st/auc",
        "c2st/gene_acc",
        "c2st/gene_auc",
    }
    missing = expected - set(metrics)
    if missing:
        raise RuntimeError(f"DKD evaluation omitted required metrics: {sorted(missing)}")
    return {key: float(metrics[key]) for key in sorted(expected)}, metadata


def held_out_condition_macro(rows: list[dict[str, object]]) -> list[dict[str, object]]:
    """Equal-weight group means followed by equal-weight condition means per metric/seed.

    This aggregation never pools emitted cells and never averages different metric keys together.
    """
    buckets: dict[tuple[object, ...], list[float]] = {}
    seen: set[tuple[object, ...]] = set()
    for row in rows:
        key = (row["condition"], row["seed"], row["comparison"], row["metric"])
        identity = (*key, row["held_out_group"])
        if identity in seen:
            raise ValueError(f"Duplicate held-out result: {identity}")
        seen.add(identity)
        buckets.setdefault(key, []).append(float(row["value"]))
    condition_means = [
        (condition, seed, comparison, metric, sum(values) / len(values))
        for (condition, seed, comparison, metric), values in buckets.items()
    ]
    final: dict[tuple[object, ...], list[float]] = {}
    for _condition, seed, comparison, metric, value in condition_means:
        final.setdefault((seed, comparison, metric), []).append(value)
    return [
        {
            "seed": seed,
            "comparison": comparison,
            "metric": metric,
            "value": sum(values) / len(values),
            "n_conditions": len(values),
        }
        for (seed, comparison, metric), values in sorted(final.items())
    ]
